INSERT INTO `COLUMNS` VALUES ('def', 'performance_schema', 'replication_asynchronous_connection_failover', 'CHANNEL_NAME', 1, NULL, 'NO', 'char', 64, 192, NULL, NULL, NULL, 'utf8mb3', 'utf8mb3_general_ci', 'char(64)', '', '', 'select,insert,update,references', 'The replication channel name that connects source and replica.', '', NULL);
INSERT INTO `COLUMNS` VALUES ('def', 'performance_schema', 'replication_asynchronous_connection_failover', 'HOST', 2, NULL, 'NO', 'char', 255, 255, NULL, NULL, NULL, 'ascii', 'ascii_general_ci', 'char(255)', '', '', 'select,insert,update,references', 'The source hostname that the replica will attempt to switch over the replication connection to in case of a failure.', '', NULL);
INSERT INTO `COLUMNS` VALUES ('def', 'performance_schema', 'replication_asynchronous_connection_failover', 'PORT', 3, NULL, 'NO', 'int', NULL, NULL, 10, 0, NULL, NULL, NULL, 'int', '', '', 'select,insert,update,references', 'The source port that the replica will attempt to switch over the replication connection to in case of a failure.', '', NULL);
INSERT INTO `COLUMNS` VALUES ('def', 'performance_schema', 'replication_asynchronous_connection_failover', 'NETWORK_NAMESPACE', 4, NULL, 'YES', 'char', 64, 256, NULL, NULL, NULL, 'utf8mb4', 'utf8mb4_0900_ai_ci', 'char(64)', '', '', 'select,insert,update,references', 'The source network namespace that the replica will attempt to switch over the replication connection to in case of a failure. If its value is empty, connections use the default (global) namespace.', '', NULL);
INSERT INTO `COLUMNS` VALUES ('def', 'performance_schema', 'replication_asynchronous_connection_failover', 'WEIGHT', 5, NULL, 'NO', 'int', NULL, NULL, 10, 0, NULL, NULL, NULL, 'int unsigned', '', '', 'select,insert,update,references', 'The order in which the replica shall try to switch the connection over to when there are failures. Weight can be set to a number between 1 and 100, where 100 is the highest weight and 1 the lowest.', '', NULL);
